sysauto_script.script:
(function executeRule(current, gPrevious) {
    var now = new GlideDateTime();
    var nextWeek = new GlideDateTime();
    nextWeek.addDaysUTC(7); // One week from today

    var budgetGR = new GlideRecord('x_1790229_event_ma_budget'); // Replace with actual budget table name
    budgetGR.addQuery('u_review_due_date', '<=', nextWeek);      // Due for review in next 7 days
    budgetGR.addQuery('u_status', '!=', 'Reviewed');             // Not yet reviewed
    budgetGR.query();

    while (budgetGR.next()) {
        var planner = budgetGR.u_event_planner; // Assuming this is a reference to sys_user

        if (planner) {
            // Send custom event for notification
            gs.eventQueue(
                'x_1790229_event_ma.budget_review_reminder',
                planner,
                budgetGR.u_event_name,                   // event.parm1
                budgetGR.u_review_due_date.getDisplayValue() // event.parm2
            );
        }
    }
})();
